import 'package:flutter/material.dart'; import 'package:supabase_flutter/supabase_flutter.dart'; class WalletScreen extends StatefulWidget{const WalletScreen({super.key}); @override State<WalletScreen> createState()=>_WalletScreenState();} class _WalletScreenState extends State<WalletScreen>{ double saldo=0; bool loading=true; @override void initState(){super.initState(); load();} Future<void> load() async {try{final uid=Supabase.instance.client.auth.currentUser?.id; if(uid!=null){final res=await Supabase.instance.client.from('wallets').select().eq('user_id',uid).maybeSingle(); if(res!=null) saldo=(res['saldo'] as num).toDouble();}}catch(e){} setState(()=> loading=false);} @override Widget build(BuildContext context){return Scaffold(backgroundColor: Color(0xFF0A0E1A), appBar: AppBar(title: Text('Minha Carteira'), backgroundColor: Colors.black), body: Center(child: Text('Saldo: R\$ \${saldo.toStringAsFixed(2)}', style: TextStyle(fontSize:32, color: Colors.white))));}}